mapper.select:
select bftr.id, bftr.status, bftr.rule_name as ruleName, bftr.rule_number as ruleNumber, bftr.api_code as apiCode, bftr.task_time as taskTime, bmc.cid ,bmc.short_name as cName, shf.zipFile_name as fileName, case when shf.status is null then 0 when shf.status=2 then 2 when shf.status=0 then 1 when shf.status=1 then 1 when shf.status=3 then 1 else '-' end as taskStatus, DATE_FORMAT(bftr.create_time,'%Y-%m-%d %H:%i:%s') as createTime, DATE_FORMAT(bftr.update_time,'%Y-%m-%d %H:%i:%s') as updateTime from b_fast_task_rule bftr left join b_marketing_customer bmc on bftr.api_code=bmc.api_code left join b_fast_file_relation bfr on bftr.id=bfr.fast_task_id left join stra_his_file shf on bfr.file_id=shf.id where bftr.is_del = 1
and bftr.status = #{status}
and (bftr.rule_name like concat("%", #{search},"%") or bftr.rule_number like concat("%", #{search},"%") or bftr.api_code like concat("%", #{search},"%") or bmc.cid like concat("%", #{search},"%"))
and bftr.create_time >=#{createTimeStart}
and bftr.create_time <#{createTimeEnd}
and bftr.update_time >=#{updateTimeStart}
and bftr.update_time <#{updateTimeEnd}
and shf.status is null and bftr.status=1
and shf.status = 2 and bftr.status=1
and shf.status in(0,1,3) and bftr.status=1
order by bftr.update_time desc,bftr.create_time desc,bftr.id desc
